(* e36 exact CNEG finite fixtures. No universal instruction/function correctness. *)
Require Import Picinae_armv8 Picinae_finterp NArith List Bool.
Import ListNotations.
Open Scope N.
(* cneg w0,w0,eq; 0014805a *)
Definition fixture_0 : stmt :=
Move (V_TEMP 0) (UnOp OP_NEG (Extract 31 0 (Var R_X0))) $;
	If (Cast CAST_LOW 1 (Var R_ZR)) (Nop) (Move (V_TEMP 0) (Extract 31 0 (Var R_X0))) $;
	Move R_X0 (Cast CAST_UNSIGNED 64 (Var (V_TEMP 0))).
